function canMeasureWater(x, y, target) {
  if (x + y < target) {
    return false;
  }
  let a = x;
  let b = y;
  while (b !== 0) {
    const remainder = a % b;
    a = b;
    b = remainder;
  }
  return target % a === 0;
}

