function canMeasureWater(x, y, target) {
  // Breadth-first search over every (first jug, second jug) state.
  const seen = new Uint8Array((x + 1) * (y + 1));
  const queue = new Int32Array((x + 1) * (y + 1) * 2);
  let head = 0, tail = 0;
  const visit = (p, q) => {
    const key = p * (y + 1) + q;
    if (seen[key]) return;
    seen[key] = 1;
    queue[tail++] = p;
    queue[tail++] = q;
  };
  visit(0, 0);
  while (head < tail) {
    const p = queue[head++], q = queue[head++];
    if (p + q === target) return true;
    const toSecond = Math.min(p, y - q), toFirst = Math.min(q, x - p);
    visit(x, q); visit(p, y); visit(0, q); visit(p, 0);
    visit(p - toSecond, q + toSecond);
    visit(p + toFirst, q - toFirst);
  }
  return false;
}

