function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'small') {
    const x = pick(1, 12), y = pick(1, 12);
    return [x, y, pick(1, Math.min(1000, x + y + 4))];
  }
  // Large cases share a common factor half the time so both answers appear.
  const factor = rand() < 0.5 ? pick(2, 40) : 1;
  const x = factor * pick(1, Math.floor(1000 / factor));
  const y = factor * pick(1, Math.floor(1000 / factor));
  const target = rand() < 0.5 ? factor * pick(1, Math.floor(1000 / factor)) : pick(1, 1000);
  return [x, y, target];
}
